local rows = {
  {id="third_intro_red", actor="RED", role="third", mapGroup="ROUTE_1|VIRIDIAN_CITY", progressGate="active-NG+-Oak-receipt|Hall-of-Fame", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="deterministic-once-per-third-identity", repeatSuppression="durable-third-introduction-receipt", category="intro", species="", en="RED: {PLAYER}.\nI'm RED.\fI heard Kanto's Champion\nstarted the road again.\fI prefer meeting strong Trainers\nto hearing stories about them.", de="RED: {PLAYER}.\nIch bin RED.\fIch hörte, Kantos Champ\nist wieder aufgebrochen.\fStarke Trainer treffe ich lieber,\nals nur von ihnen zu hören.", sourceLine="tools/build_life_of_rival_dialogues_67.py:103"},
  {id="third_intro_blue", actor="BLUE", role="third", mapGroup="ROUTE_1|VIRIDIAN_CITY", progressGate="active-NG+-Oak-receipt|Hall-of-Fame", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="deterministic-once-per-third-identity", repeatSuppression="durable-third-introduction-receipt", category="intro", species="", en="BLUE: So you're {PLAYER}.\nI'm BLUE.\fAnother run through Kanto?\nGood. I wanted a benchmark.\fTry not to make my first result\ntoo easy.", de="BLUE: Du bist also {PLAYER}.\nIch bin BLUE.\fNoch eine Runde durch Kanto?\nGut. Ich wollte einen Vergleich.\fMach es mir beim ersten Duell\nnicht zu leicht.", sourceLine="tools/build_life_of_rival_dialogues_67.py:108"},
  {id="third_intro_green", actor="GREEN", role="third", mapGroup="ROUTE_1|VIRIDIAN_CITY", progressGate="active-NG+-Oak-receipt|Hall-of-Fame", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="deterministic-once-per-third-identity", repeatSuppression="durable-third-introduction-receipt", category="intro", species="", en="GREEN: Hi, {PLAYER}!\nI'm GREEN.\fI'm studying how Kanto's\nChampion crosses the region.\fYour reputation got here first.\nWant to compare field notes?", de="GREEN: Hi, {PLAYER}!\nIch bin GREEN.\fIch will wissen, wie man als Champ\ndurch Kanto reist.\fVon dir reden hier schon alle.\nTauschen wir unsere Notizen?", sourceLine="tools/build_life_of_rival_dialogues_67.py:113"},
  {id="red_standard_quiet_pace", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: I reviewed our last battle.\fYou waited for the opening.\nI won't leave it twice.", de="RED: Ich habe unseren Kampf\nanalysiert.\fDu hast auf die Lücke gewartet.\nDie lasse ich dir kein zweites Mal.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_standard_kind_rest", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: Your team fought hard.\fLet them recover first.\nThe rematch can wait.", de="RED: Dein Team kämpfte hart.\fLass es sich erst erholen.\nDie Revanche kann warten.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_standard_champion_watch", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: We skipped the battle.\fWise, if your team needed rest.\nThe offer still stands.", de="RED: Wir ließen den Kampf aus.\fGut, falls dein Team Ruhe brauchte.\nMein Angebot bleibt.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_standard_small_nod", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: Your lead looks settled.\fThe road is building trust.\nThat matters in a battle.", de="RED: Dein erstes Pokémon ist ruhig.\fUnterwegs wächst euer Vertrauen.\nDas zählt im Kampf.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_standard_shared_road", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: I checked the far grass.\fFewer tracks, clearer pattern.\nTry the near edge next.", de="RED: Ich habe den fernen Grasrand\ngeprüft. Dort sind weniger Spuren.\fVersuch es als Nächstes\nam nahen Rand.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_standard_patient_win", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="RED: A trophy marks one day.\fA team's trust marks\nthe whole journey.", de="RED: Ein Pokal steht für einen Tag.\fDas Vertrauen eines Teams\nfür die ganze Reise.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_pace_receipt", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: I reviewed that battle.\fYou found one opening.\nDon't expect the same one twice.", de="BLUE: Ich habe den Kampf geprüft.\fDu hast genau eine Lücke gefunden.\nDie bekommst du nicht noch mal.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_route_rank", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: Last battle set the rank.\fFor now. Train up.\nI want a better test.", de="BLUE: Der letzte Kampf zeigte,\nwo wir stehen.\fTrainiere weiter. Beim nächsten Mal\nwill ich mehr von dir sehen.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_team_answer", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: You skipped our battle.\fFine. Bring a team\nworth the wait.", de="BLUE: Du hast unseren Kampf\nausgelassen. Na gut.\fBring nächstes Mal ein Team mit,\nfür das sich das Warten lohnt.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_history_edit", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: I log every matchup.\fPatterns are easier to beat\nonce they think they're secret.", de="BLUE: Ich notiere jedes Duell.\fMuster sind leicht zu knacken,\nsobald ich sie erkannt habe.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_shortcut_tax", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: I checked both routes.\fThe shorter one is slower.\nYes, I tested it first.", de="BLUE: Ich prüfte beide Wege.\fDer kürzere ist langsamer.\nJa, ich testete ihn zuerst.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="blue_standard_rival_standard", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="BLUE: Rivals set the standard.\fMine stays just high enough\nfor you to keep chasing.", de="BLUE: Rivalen setzen Maßstäbe.\fMeiner bleibt hoch genug,\ndamit du dich weiter anstrengst.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_map_upside_down", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: I reviewed our last battle.\fYour adjustment beat my model.\nI brought a better one.", de="GREEN: Ich habe mir unseren\nletzten Kampf angesehen.\fDu hast meinen Plan durchkreuzt.\nJetzt habe ich einen besseren.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_snack_variable", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: My last plan worked.\fI kept the useful parts\nand questioned the lucky ones.", de="GREEN: Mein letzter Plan ging auf.\fWas gut war, behalte ich.\nDen Rest probiere ich noch mal.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_three_plans", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: No battle last time.\fFair. I used the gap\nto test a new lead.", de="GREEN: Letztes Mal haben wir\nnicht gekämpft.\fAlso habe ich gewartet und\nmein erstes Pokémon gewechselt.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_field_notes", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: I marked the safe turn.\fTwice: once for the route,\nonce so I remember it.", de="GREEN: Ich habe die sichere\nAbzweigung markiert.\fZweimal: einmal auf der Karte\nund einmal für mich.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_compass_lunch", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: Every route needs a plan.\fMine leaves room to be wrong.\nThat's how it gets better.", de="GREEN: Für jede Route brauche ich\neinen Plan.\fMeiner darf auch mal falsch sein.\nDann mache ich ihn besser.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="green_standard_competent_detour", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="context-priority-then-random-within-current-scene-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="standard", species="", en="GREEN: I tested one detour.\fSeven extra steps,\nbut a much clearer trail.", de="GREEN: Ich nahm den anderen Weg.\fSieben Schritte mehr,\naber die Spur war viel klarer.", sourceLine="tools/build_life_of_rival_dialogues_67.py:153"},
  {id="red_map_route", actor="RED", role="rival-or-third", mapGroup="route", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="RED: Open road.\fWatch the grass edge.\nYour partner already does.", de="RED: Freie Route.\fAchte auf den Grasrand.\nDein Partner tut es schon.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="red_map_city", actor="RED", role="rival-or-third", mapGroup="city", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="RED: Busy streets.\fSlow down near corners.\nKindness needs room.", de="RED: Belebte Straßen.\fGeh an den Ecken langsamer.\nNimm Rücksicht auf andere.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="red_map_coast", actor="RED", role="rival-or-third", mapGroup="coast", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="RED: Salt on the wind.\fWater teams read it first.\nListen to yours.", de="RED: Salz liegt in der Luft.\fWasser-Pokémon spüren ihn zuerst.\nAchte auf deins.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="red_map_forest", actor="RED", role="rival-or-third", mapGroup="forest-edge", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="RED: The trees quiet the road.\fGood place to hear\na nervous partner.", de="RED: Die Bäume dämpfen den Weg.\fHier hört man\neinen nervösen Partner.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="blue_map_route", actor="BLUE", role="rival-or-third", mapGroup="route", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="BLUE: Long straightaway.\fPerfect for measuring\nhow far behind you are.", de="BLUE: Lange Gerade.\fPerfekt, um zu messen,\nwie weit du zurückliegst.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="blue_map_city", actor="BLUE", role="rival-or-third", mapGroup="city", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="BLUE: Crowded city.\fEveryone recognizes me.\nSome need a second look.", de="BLUE: Volle Stadt.\fAlle erkennen mich.\nManche brauchen zwei Blicke.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="blue_map_coast", actor="BLUE", role="rival-or-third", mapGroup="coast", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="BLUE: Coastal wind.\fBad for hair. Great for\nremoving weak excuses.", de="BLUE: Küstenwind.\fSchlecht fürs Haar. Gut gegen\nschwache Ausreden.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="blue_map_forest", actor="BLUE", role="rival-or-third", mapGroup="forest-edge", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="BLUE: Forest shade.\fUseful when the spotlight\ngets tired of following me.", de="BLUE: Waldschatten.\fNützlich, wenn mein Scheinwerfer\neine Pause braucht.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="green_map_route", actor="GREEN", role="rival-or-third", mapGroup="route", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="GREEN: Crosswind carries scent.\fSearch the lee side of the grass.\nThe trail lingers longer there.", de="GREEN: Der Wind trägt Gerüche fort.\fSuch hinter dem hohen Gras.\nDort bleibt die Spur länger.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="green_map_city", actor="GREEN", role="rival-or-third", mapGroup="city", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="GREEN: Street noise hides steps.\fCheck the quiet side streets.\nTracks last longer there.", de="GREEN: Im Straßenlärm hört man\nSchritte kaum.\fSuch in den ruhigen Seitengassen.\nDort bleiben Spuren länger.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="green_map_coast", actor="GREEN", role="rival-or-third", mapGroup="coast", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="GREEN: The tide erases evidence.\fCheck above the waterline.\nThe dry prints last.", de="GREEN: Die Flut löscht Spuren.\fSuch oberhalb der Wasserlinie.\nDort bleiben Abdrücke trocken.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="green_map_forest", actor="GREEN", role="rival-or-third", mapGroup="forest-edge", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-map-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="map", species="", en="GREEN: Moss marks the old trail.\fFollow the fresh leaves instead.\nThey were moved recently.", de="GREEN: Moos zeigt die alte Spur.\fFolge lieber frischen Blättern.\nSie wurden erst kürzlich bewegt.", sourceLine="tools/build_life_of_rival_dialogues_67.py:177"},
  {id="red_progress_ngplus", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="ngplus", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: A new beginning.\fOld lessons, deeper trust.\nThat's worth the climb.", de="RED: Ein neuer Anfang.\fAlte Lehren, tieferes Vertrauen.\nDafür lohnt der Aufstieg.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="red_progress_master", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="master_gyms", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: The Leaders train again.\fSo do their teams.\nMeet them rested.", de="RED: ARENALEITER trainieren wieder.\fIhre Teams auch.\nTritt nur gut erholt gegen sie an.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="red_progress_apex", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="apex_elite", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: The Leaders are down.\nThe ELITE FOUR study losses.\fEnter with more than one answer.\nEach room changes the test.", de="RED: Die Leiter sind besiegt.\nDie TOP VIER lernen aus Fehlern.\fGeh mit mehr als einer Antwort.\nJeder Raum ändert die Prüfung.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="red_progress_legend", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="legend_hunt", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: Legends leave quiet signs.\fDon't chase the loudest.\nProtect the trail.", de="RED: Legenden zeigen\nleise Zeichen.\fJage nicht dem lautesten nach.\nSchütze die Spur.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="red_progress_crown", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="crown_gyms|crown_elite", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: A crown is duty.\fCarry it without crushing\nwho helped you rise.", de="RED: Eine Krone ist Pflicht.\fTrag sie, ohne jene zu erdrücken,\ndie dir halfen.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="red_progress_complete", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="complete", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="RED: You reached the summit.\fGood. Now guide someone\nthrough their first hill.", de="RED: Du bist am Gipfel.\fGut. Führe nun jemanden\nüber den ersten Hügel.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="blue_progress_ngplus", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="ngplus", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="BLUE: Starting over?\fSmart. Your old record\nneeded a better rival.", de="BLUE: Noch mal von vorn?\fKlug. Dein alter Rekord\nbrauchte einen besseren Rivalen.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="blue_progress_master", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="master_gyms", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="BLUE: Master battles?\fFinally, a challenge\nworthy of my name.", de="BLUE: Meisterkämpfe?\fEndlich eine Herausforderung,\ndie meinen Namen verdient.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="blue_progress_apex", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="apex_elite", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="BLUE: Master circuit cleared?\nNow the ELITE FOUR set the rank.\fLet's see who reaches\nthe Champion room first.", de="BLUE: Meisterrunde geschafft?\nNun bestimmen die TOP VIER.\fMal sehen, wer zuerst\nden Champ-Raum erreicht.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
  {id="blue_progress_legend", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="legend_hunt", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="first-unseen-current-phase-then-context-pool", repeatSuppression="exclude-current-appearance-and-last-24-per-actor", category="progress", species="", en="BLUE: Hunting legends?\fI mapped the fast route.\nNo, you can't copy it.", de="BLUE: Legendenjagd?\fIch kenne den schnellen Weg.\nNein, du darfst nicht abschreiben.", sourceLine="tools/build_life_of_rival_dialogues_67.py:208"},
