  {id="red_battle_prompt", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="RED: Would you honor me\nwith a battle?", de="RED: Kämpfst du gegen mich?", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="red_battle_decline", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="RED: Of course.\fWe'll choose a better moment.", de="RED: Schon gut.\fDann ein andermal.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="red_battle_win", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="RED: Well fought.\fYou earned this one.\nI'll claim the next.", de="RED: Gut gekämpft.\fDiesen Sieg hast du verdient.\nDen nächsten hole ich mir.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="red_battle_lose", actor="RED", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="RED: Strong battle.\fHeal your team.\nI'll expect your best.", de="RED: Starker Kampf.\fHeile dein Team.\nIch erwarte dein Bestes.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="blue_battle_prompt", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="BLUE: Does your lead deserve\nits spot? Prove it.", de="BLUE: Dein erstes Pokémon\nsoll das Team anführen?\fDann beweis es.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="blue_battle_decline", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="BLUE: Wise choice.\fFor now, I keep\nmy best plan hidden.", de="BLUE: Kluge Wahl.\fVorerst bleibt mein\nbester Plan geheim.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="blue_battle_win", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="BLUE: You got me.\fEnjoy the headline.\nI'm writing the sequel.", de="BLUE: Du warst besser.\fGenieß deinen Sieg.\nBeim nächsten Mal bin ich dran.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="blue_battle_lose", actor="BLUE", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="BLUE: Lead defended.\fTrain up. Make the rematch count.", de="BLUE: Die Führung bleibt bei mir.\fTrainiere weiter. Bei der Revanche\nwill ich dein Bestes sehen.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="green_battle_prompt", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="GREEN: Want a battle?\fI have a theory about your lead.\nLet's test it properly.", de="GREEN: Lust auf einen Kampf?\fIch habe eine Idee zu deinem\nersten Pokémon. Probieren wir's.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="green_battle_decline", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="GREEN: All right.\fObservation first, battle later.\nThat still counts as progress.", de="GREEN: In Ordnung.\fErst beobachten, später kämpfen.\nAuch das ist Fortschritt.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="green_battle_win", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="GREEN: You win!\fYour adjustments\nbroke my whole model.\fGood. Now I can improve it.", de="GREEN: Du gewinnst!\fDu hast meinen ganzen Plan\nauf den Kopf gestellt.\fGut. Jetzt weiß ich,\nwas ich besser machen kann.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="green_battle_lose", actor="GREEN", role="rival-or-third", mapGroup="all-eligible-outdoors", progressGate="any", requiredAuthority="none", requiredReceipt="none", weight=1, selectionRule="fixed-by-battle-transaction-result", repeatSuppression="not-randomly-selected", category="battle", species="", en="GREEN: That worked!\fI changed the plan mid-battle.\nThe notes can catch up later.", de="GREEN: Das hat geklappt!\fIm Kampf änderte ich den Plan.\nNotizen mache ich später.", sourceLine="tools/build_life_of_rival_dialogues_67.py:293"},
  {id="red_followup_route",actor="RED",role="rival-or-third",mapGroup="route",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="RED: I'm staying here.\fThere's more to learn.",de="RED: Ich bleibe noch hier.\fEs gibt noch etwas zu lernen.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="red_followup_city",actor="RED",role="rival-or-third",mapGroup="city",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="RED: Rest first.\fThen we move on.",de="RED: Erst ausruhen.\fDann geht es weiter.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="red_duel_wait",actor="RED",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="RED: Not now.\fThis battle isn't over.",de="RED: Nicht jetzt.\fDer Kampf ist noch nicht vorbei.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="red_duel_next",actor="RED",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel-next-5-percent",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="RED: You're next.\fIf you want the battle.",de="RED: Du bist als Nächstes dran.\fWenn du kämpfen willst.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="blue_followup_route",actor="BLUE",role="rival-or-third",mapGroup="route",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="BLUE: Still here?\fGood. Watch how it's done.",de="BLUE: Immer noch hier?\fGut. Dann sieh genau hin.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="blue_followup_city",actor="BLUE",role="rival-or-third",mapGroup="city",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="BLUE: Even the best team\fneeds a short break.",de="BLUE: Selbst das beste Team\fbraucht mal eine kurze Pause.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="blue_duel_wait",actor="BLUE",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="BLUE: Not now!\fI'm about to win this.",de="BLUE: Nicht jetzt!\fIch gewinne das hier gleich.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="blue_duel_next",actor="BLUE",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel-next-5-percent",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="BLUE: You're next.\fTry to make it interesting.",de="BLUE: Danach bist du dran.\fMach es wenigstens spannend.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="green_followup_route",actor="GREEN",role="rival-or-third",mapGroup="route",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="GREEN: Wait! I found\fanother set of tracks.",de="GREEN: Warte!\fIch habe noch eine andere\nSpur gefunden.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="green_followup_city",actor="GREEN",role="rival-or-third",mapGroup="city",progressGate="any",requiredAuthority="none",requiredReceipt="visit-talk",weight=1,selectionRule="fixed-repeat-talk",repeatSuppression="receipt-once",category="followup",species="",en="GREEN: My team is resting.\fI'm getting snacks.",de="GREEN: Mein Team ruht sich aus.\fIch hole uns etwas zu essen.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="green_duel_wait",actor="GREEN",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="GREEN: Not now!\fI just thought of something.",de="GREEN: Nicht jetzt!\fIch habe gerade eine Idee.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
  {id="green_duel_next",actor="GREEN",role="rival-or-third",mapGroup="all",progressGate="any",requiredAuthority="none",requiredReceipt="duel-next-5-percent",weight=1,selectionRule="fixed-duel",repeatSuppression="visit-stable",category="duel",species="",en="GREEN: Want the next battle?\fI want to try one more idea.",de="GREEN: Willst du danach kämpfen?\fIch möchte noch etwas ausprobieren.",sourceLine="life_of_rival_dialogue_data.lua:visit"},
}

-- Every German line below was reviewed as spoken dialogue, not as a literal
-- translation. Red stays quiet and considerate, Blue competitive and cocky,
-- and Green curious without sounding like an adult report or laboratory log.
local german={
  third_intro_red="RED: {PLAYER}.\nIch bin RED.\fAlle sagen, Kantos Champ\nzieht wieder los.\fStarke Trainer treffe ich lieber,\nals nur von ihnen zu hören.",
  third_intro_blue="BLUE: Du bist also {PLAYER}.\nIch bin BLUE.\fDu reist noch mal durch Kanto?\nGut. Dann sehe ich, was du kannst.\fMach es mir beim ersten Duell\nnicht zu leicht.",
  third_intro_green="GREEN: Hi, {PLAYER}!\nIch bin GREEN.\fIch will sehen, wie ein Champ\ndurch Kanto reist.\fAlle reden schon von dir.\nSuchen wir zusammen nach Spuren?",

  red_standard_quiet_pace="RED: Ich dachte noch mal\nüber unseren Kampf nach.\fDu hast deine Chance genutzt.\nDie bekommst du nicht noch mal.",
  red_standard_kind_rest="RED: Dein Team hat hart gekämpft.\fLass es sich erst ausruhen.\nDie Revanche kann warten.",
  red_standard_champion_watch="RED: Wir haben nicht gekämpft.\fSchon gut. Dein Team brauchte Ruhe.\nMein Angebot steht noch.",
  red_standard_small_nod="RED: Dein erstes Pokémon\nwirkt ganz ruhig.\fIhr vertraut euch.\nDas hilft auch im Kampf.",
  red_standard_shared_road="RED: Hinten am Gras waren\nnur wenige Spuren.\fSchau beim nächsten Mal\nam vorderen Rand nach.",
  red_standard_patient_win="RED: Ein Pokal erinnert\nan einen einzigen Tag.\fDas Vertrauen deines Teams\nbleibt viel länger.",
  blue_standard_pace_receipt="BLUE: Ich habe mir den Kampf\nnoch mal angesehen.\fDu hattest genau eine Chance.\nDie bekommst du nicht noch mal.",
  blue_standard_route_rank="BLUE: Jetzt weiß ich,\nwie gut wir beide sind.\fTrainier weiter. Beim nächsten Mal\nwill ich mehr von dir sehen.",
  blue_standard_team_answer="BLUE: Du wolltest nicht kämpfen?\nNa gut.\fBring nächstes Mal ein Team mit,\nfür das sich das Warten lohnt.",
  blue_standard_history_edit="BLUE: Ich merke mir jedes Duell.\fWenn ich deinen Trick kenne,\nfunktioniert er nicht noch mal.",
  blue_standard_shortcut_tax="BLUE: Ich kenne jetzt beide Wege.\fDer kurze dauert länger.\nJa, ich war zuerst dort.",
  blue_standard_rival_standard="BLUE: Ein guter Rivale\nmacht dich stärker.\fAlso streng dich an.\nIch warte nicht auf dich.",
  green_standard_map_upside_down="GREEN: Ich habe über unseren\nletzten Kampf nachgedacht.\fDu hast meinen Plan durchkreuzt.\nJetzt habe ich einen besseren.",
  green_standard_snack_variable="GREEN: Mein letzter Plan ging auf.\fWas gut war, behalte ich.\nDen Rest probiere ich anders.",
  green_standard_three_plans="GREEN: Letztes Mal haben wir\nnicht gekämpft.\fAlso habe ich gewartet und\nmein erstes Pokémon gewechselt.",
  green_standard_field_notes="GREEN: Diese Abzweigung\nist sicher.\fIch habe sie auf der Karte\nextra dick markiert.",
  green_standard_compass_lunch="GREEN: Ich plane meine Route.\fWenn ich mich irre,\nprobiere ich eben etwas anderes.",
  green_standard_competent_detour="GREEN: Ich nahm den anderen Weg.\fEr war etwas länger,\naber dort sah ich mehr Spuren.",

  red_map_route="RED: Eine freie Route.\fAchte auf den Grasrand.\nDein Partner tut es schon.",
  red_map_city="RED: Hier ist viel los.\fGeh an den Ecken langsamer.\nDann stößt du niemanden um.",
  red_map_coast="RED: Man riecht das Meer.\fDein Wasser-Pokémon merkt es auch.\nAchte auf seine Reaktion.",
  red_map_forest="RED: Im Wald ist es still.\fSo merkst du schnell,\nwenn dein Partner nervös wird.",
  blue_map_route="BLUE: Eine lange Gerade.\fPerfekt, um zu sehen,\nwie weit du hinter mir bist.",
  blue_map_city="BLUE: Ganz schön voll hier.\fTrotzdem erkennen mich alle.\nNa ja, fast alle.",
  blue_map_coast="BLUE: Dieser Küstenwind!\fSchlecht für meine Haare,\naber gut zum Trainieren.",
  blue_map_forest="BLUE: Im Wald gibt es Schatten.\fGanz praktisch, wenn alle\nständig auf mich schauen.",
  green_map_route="GREEN: Der Wind trägt Gerüche fort.\fSuch hinter dem hohen Gras.\nDort bleibt die Spur länger.",
  green_map_city="GREEN: Hier ist es laut.\fMein Team hat eine ruhige Bank.\nFür dich ist noch Platz.",
  green_map_coast="GREEN: Die Flut verwischt Spuren.\fSuch weiter oben am Ufer.\nDort bleiben die Abdrücke.",
  green_map_forest="GREEN: Das Moos ist schon alt.\fFolge lieber den frischen Blättern.\nDa ging gerade jemand entlang.",

  red_progress_ngplus="RED: Ein neuer Anfang.\fDu kennst den Weg schon.\nDein Team kennt dich auch.",
  red_progress_master="RED: Die ARENALEITER\ntrainieren wieder.\fIhre Teams sind stärker.\nGeh nur gut erholt hinein.",
  red_progress_apex="RED: Die Orden hast du.\nJetzt kommen die TOP VIER.\fVerlass dich nicht nur\nauf einen einzigen Plan.",
  red_progress_legend="RED: Legenden hinterlassen\nnur leise Zeichen.\fNimm dir Zeit.\nUnd beschütze ihre Spuren.",
  red_progress_crown="RED: Als Champ hast du Pflichten.\fVergiss dabei nie,\nwer dir geholfen hat.",
  red_progress_complete="RED: Du hast alles geschafft.\fHilf jetzt jemandem\nbei den ersten Schritten.",
  blue_progress_ngplus="BLUE: Noch mal von vorn?\fGut. Mein alter Rekord\nbraucht einen besseren Gegner.",
  blue_progress_master="BLUE: Meisterkämpfe?\fEndlich Gegner,\ndie meinen Namen kennen sollten.",
  blue_progress_apex="BLUE: Alle Orden? Nicht schlecht.\fMal sehen, wer zuerst\nbei den TOP VIER ankommt.",
  blue_progress_legend="BLUE: Du suchst Legenden?\fIch kenne den schnelleren Weg.\nNein, ich verrate ihn nicht.",
  blue_progress_crown="BLUE: Die Krone steht dir.\fAber an mir\nsähe sie noch besser aus.",
  blue_progress_complete="BLUE: Du hast alles geschafft?\fPerfekt. Dann lohnt es sich ja,\ndeinen Rekord zu brechen.",
  green_progress_ngplus="GREEN: Neue Reise, alte Wege.\fMal sehen,\nwas diesmal anders ist.",
  green_progress_master="GREEN: Die Leiter kennen\ndeinen ersten Plan schon.\fNimm noch einen mit.\nNur stärker reicht nicht immer.",
  green_progress_apex="GREEN: Ein Leiter prüft\nnur einen Kampf.\fBei den TOP VIER brauchst du\nmehr als einen guten Trick.",
  green_progress_legend="GREEN: Ich habe drei Hinweise.\fZwei führen in dieselbe Richtung.\fAlso probiere ich den dritten.",
  green_progress_crown="GREEN: Ein Champ zieht\nviele Herausforderer an.\fGut! Mein Team braucht\neinen richtig starken Gegner.\fDeins sieht auch bereit aus.",
  green_progress_complete="GREEN: Mein Heft ist voll.\fJetzt will ich herausfinden,\nwie ich anderen Trainern helfe.",

  red_title="RED: {TITLE}.\fDer Titel passt. Im nächsten Kampf\nwill ich ihn dir abjagen.",
  blue_title="BLUE: {TITLE}?\fGuter Titel. CHAMP klingt besser.\nIch zeige dir gern, warum.",
  green_title="GREEN: {TITLE}!\fDer Titel passt wirklich zu dir.\nIch kenne sogar drei Gründe.\fDen vierten finden wir\nim nächsten Kampf.",

  red_search_track="RED: Ich suche {SPECIES}\nauf {MAP}.\fWenn es mitkommen will,\ngehen wir zusammen weiter.",
  red_search_listen="RED: Wegen {SPECIES}\nbin ich auf {MAP}.\fErst beobachte ich es.\nDann frage ich, ob es mitkommt.",
  red_search_partner="RED: Ein {SPECIES} von {MAP}\nkönnte gut zu uns passen.\fKeine Eile.\nEs darf selbst entscheiden.",
  blue_search_track="BLUE: Ich brauche ein {SPECIES}\nvon {MAP}.\fEs macht mein Team noch besser.\nDas fiel mir vor dir auf.",
  blue_search_listen="BLUE: Ich suche {SPECIES}\nauf {MAP}.\fEin gutes Team ist vorbereitet,\nbevor es schwierig wird.",
  blue_search_partner="BLUE: Nächstes Ziel: {SPECIES}\nauf {MAP}.\fGut trainiert macht es\nmein bestes Team noch besser.",
  green_search_track="GREEN: Ich suche {SPECIES}\nauf {MAP}.\fErst finde ich einen Abdruck.\nDann folge ich der Spur.",
  green_search_listen="GREEN: Ich suche {SPECIES}\nbei {MAP}.\fIch möchte sehen,\nwie es dort zurechtkommt.",
  green_search_partner="GREEN: Ein {SPECIES} von {MAP}\nwürde gut zu uns passen.\fWenn es mitkommt, zeigen wir ihm\nden langen, schönen Weg.",

  red_rumor_turtwig="RED: Kleine runde Spuren\nführen nach {MAP}.\fDort versteckt sich wohl\neine Schildkröte mit Blatt.",
  blue_rumor_turtwig="BLUE: Bei {MAP} sah jemand\neine Schildkröte mit Blatt.\fDie Richtung stimmt.\nVersuch, mitzuhalten.",
  green_rumor_turtwig="GREEN: Kleine Bissspuren\nführen nach {MAP}.\fSie sehen aus wie Blätter.\nVielleicht war es eine Schildkröte.",
  red_rumor_chimchar="RED: Warme Handabdrücke\nliegen bei {MAP}.\fVielleicht war es ein Äffchen\nmit einer Flamme am Schweif.",
  blue_rumor_chimchar="BLUE: Über {MAP} steigt Rauch auf.\fEs ist kein Lagerfeuer.\nDie Spuren springen kreuz und quer.",
  green_rumor_chimchar="GREEN: Bei {MAP} liegen Ruß\nund angeknabbertes Obst.\fDie Spuren führen nach oben.\nSchau auf die warmen Steine.",
  red_rumor_piplup="RED: Kleine Fußspuren\nkommen bei {MAP} aus dem Wasser.\fEin kleiner Pinguin setzte\njeden Schritt ganz genau.",
  blue_rumor_piplup="BLUE: Bei {MAP} wurde\nein kleiner Pinguin gesehen.\fEr wollte keine Hilfe.\nGute Haltung.",
  green_rumor_piplup="GREEN: Kaltes Wasser und Federn\nfindet man bei {MAP}.\fDie Spuren führen vom Ufer weg.\nSchau am schattigen Hang nach.",
  red_rumor_snivy="RED: Eine schmale Spur zieht\ndurch das Gras bei {MAP}.\fEine kleine grüne Schlange\nließ keinen Halm umknicken.",
  blue_rumor_snivy="BLUE: Achte bei {MAP}\nauf das gerade Gras.\fDort ist eine grüne Schlange.\nSie versteckt sich besser als du.",
  green_rumor_snivy="GREEN: Das Gras bei {MAP}\nbildet eine Spur wie ein S.\fSie meidet den Hauptweg.\nSuch am ruhigen Rand.",
  red_rumor_tepig="RED: Der Boden bei {MAP}\nist an einigen Stellen warm.\fVielleicht hat dort ein Ferkel\nmit seiner Schnauze gewühlt.",
  blue_rumor_tepig="BLUE: Bei {MAP} hörte jemand\nein lautes Schnüffeln.\fFolge einfach den warmen Stellen.\nSogar du schaffst das.",
  green_rumor_tepig="GREEN: Bei {MAP} ist der Boden\nan einigen Stellen warm.\fKleine Hufspuren führen\ngegen den Wind.",
  red_rumor_oshawott="RED: Eine Muschel zog bei {MAP}\neine Linie durch den Sand.\fEin junger Otter übte dort.\nLass ihm etwas Platz.",
  blue_rumor_oshawott="BLUE: Bei {MAP} sind\nMuschelspuren am Ufer.\fDer Otter dahinter bewegt sich\nsauberer als dein Team.",
  green_rumor_oshawott="GREEN: Bei {MAP} sind\nMuschelrillen am Ufer.\fSie enden an einer glatten Stelle.\nWarte dort am ruhigen Wasser.",
  red_rumor_chespin="RED: Bei {MAP} liegen\nSamenhüllen unter den Dornen.\fEin kleiner stacheliger Bewohner\nsucht dort wohl nach Futter.",
  blue_rumor_chespin="BLUE: Unter den Büschen bei {MAP}\nliegen Kastanienhüllen.\fDort versteckt sich etwas\nmit einer ziemlich harten Schale.",
  green_rumor_chespin="GREEN: Bei {MAP} liegen Hüllen\nund kleine Spuren unter Dornen.\fNimm die offene Seite.\nDort bleiben deine Ärmel heil.",
  red_rumor_fennekin="RED: Kleine Spuren enden\nauf warmen Steinen bei {MAP}.\fDort lauscht wohl ein Fuchs\nmit sehr großen Ohren.",
  blue_rumor_fennekin="BLUE: Bei {MAP} wurde ein Fuchs\nmit riesigen Ohren gesehen.\fEr hat dich wahrscheinlich\nschon vor drei Routen gehört.",
  green_rumor_fennekin="GREEN: Bei {MAP} liegt\nein warmer Fellbüschel.\fDie kleinen Spuren halten oft an.\nGeh leise gegen den Wind.",
  red_rumor_froakie="RED: Bei {MAP} kleben\nSchaumringe an den Blättern.\fEin kleiner Frosch zog dort\ndurch den stillen Teich.",
  blue_rumor_froakie="BLUE: Schaum auf den Blättern\nbei {MAP}.\fEine Froschspur, obwohl es\nnicht geregnet hat. Bitte sehr.",
  green_rumor_froakie="GREEN: Bei {MAP} kleben\nSchaumringe an den Blättern.\fSie sind höher als das Wasser.\nSuch beim stillsten Teich.",
  red_rumor_rowlet="RED: Runde Flügelspuren liegen\nim Staub bei {MAP}.\fDort landete eine kleine Eule.\nSchau auch über den Weg.",
  blue_rumor_rowlet="BLUE: Eine runde Eule\nbeobachtet {MAP}.\fSie schaut öfter hinter sich\nals du. Lern was daraus.",
  green_rumor_rowlet="GREEN: Bei {MAP} liegen runde\nFlügelspuren und leise Federn.\fDie Spur endet unter einem Ast.\nSchau nach oben.",
  red_rumor_litten="RED: Rußige Pfoten kreuzen\nden Weg bei {MAP}.\fEin kleines Kätzchen hielt wohl\nseinen Schweif vom Gebüsch fern.",
  blue_rumor_litten="BLUE: Schwarze Pfotenabdrücke\nbei {MAP}.\fDas Kätzchen ist vorsichtig.\nLern etwas von ihm.",
  green_rumor_litten="GREEN: Rußige Pfoten kreuzen\nden Weg bei {MAP}.\fHier war kein Lagerfeuer.\nFühl nach warmen Blättern.",
  red_rumor_popplio="RED: Eine glatte Spur führt\nbei {MAP} ins Wasser.\fDort spielt wohl\nein junger Seelöwe.",
  blue_rumor_popplio="BLUE: Hör bei {MAP}\nauf ein Klatschen.\fDort tritt ein kleiner Seelöwe auf.\nEr hat schon Publikum.",
  green_rumor_popplio="GREEN: Eine glatte Spur führt\nbei {MAP} ins Wasser.\fVom Wasser hört man Klatschen.\nDa scheint jemand Spaß zu haben.",

  red_battle_prompt="RED: Kämpfst du gegen mich?",
  red_battle_decline="RED: Schon gut.\fDann ein andermal.",
  red_battle_win="RED: Gut gekämpft.\fDiesen Sieg hast du verdient.\nDen nächsten hole ich mir.",
  red_battle_lose="RED: Das war ein guter Kampf.\fRuh dich mit deinem Team aus.\nDann kämpfen wir wieder.",
  blue_battle_prompt="BLUE: Führt dein erstes Pokémon?\nDann zeig mir, was es kann.",
  blue_battle_decline="BLUE: Du traust dich nicht?\fNa gut. Dann bleibt mein\nbester Plan noch geheim.",
  blue_battle_win="BLUE: Du warst diesmal besser.\fGenieß deinen Sieg.\nBeim nächsten Mal bin ich dran.",
  blue_battle_lose="BLUE: Ich bleibe vorn.\fTrainier weiter. Bei der Revanche\nwill ich dein Bestes sehen.",
  green_battle_prompt="GREEN: Lust auf einen Kampf?\fIch habe eine Idee zu deinem\nersten Pokémon. Probieren wir's.",
  green_battle_decline="GREEN: In Ordnung.\fDann beobachte ich noch ein wenig.\nSpäter kämpfen wir.",
  green_battle_win="GREEN: Du gewinnst!\fDu hast meinen Plan\nkomplett durchkreuzt.\fGut. Jetzt weiß ich,\nwas ich anders machen muss.",
  green_battle_lose="GREEN: Das hat geklappt!\fMitten im Kampf hatte ich\neine bessere Idee.",
}
local english={
  third_intro_red="RED: {PLAYER}.\nI'm RED.\fThey say Kanto's Champion\nis back on the road.\fI'd rather meet strong Trainers\nthan just hear about them.",
  third_intro_blue="BLUE: So you're {PLAYER}.\nI'm BLUE.\fAnother trip through Kanto?\nGood. Let's see what you can do.\fDon't make our first battle\ntoo easy.",
  third_intro_green="GREEN: Hi, {PLAYER}!\nI'm GREEN.\fI want to see how a Champion\ntravels through Kanto.\fEveryone's talking about you.\nWant to look for tracks together?",

  red_standard_quiet_pace="RED: I thought about\nour last battle.\fYou took your chance.\nYou won't get it twice.",
  red_standard_champion_watch="RED: We didn't battle.\fThat's fine. Your team needed rest.\nMy offer still stands.",
  red_standard_shared_road="RED: There weren't many tracks\nat the far side of the grass.\fTry the near edge\nnext time.",
  red_standard_patient_win="RED: A trophy lasts one day.\fThe trust of your team\nlasts much longer.",
  blue_standard_pace_receipt="BLUE: I watched that battle again.\fYou got one chance.\nYou won't get the same one twice.",
  blue_standard_route_rank="BLUE: Now I know\nhow good we both are.\fKeep training. Next time,\nI want a better battle.",
  blue_standard_history_edit="BLUE: I remember every battle.\fOnce I know your trick,\nit won't work twice.",
  blue_standard_rival_standard="BLUE: A good rival\nmakes you stronger.\fSo keep up.\nI won't wait for you.",
  green_standard_map_upside_down="GREEN: I thought about\nour last battle.\fYou beat my plan.\nNow I have a better one.",
  green_standard_snack_variable="GREEN: My last plan worked.\fI'll keep what was good\nand try the rest another way.",
  green_standard_three_plans="GREEN: We didn't battle\nlast time.\fSo I waited and changed\nmy lead Pokemon.",
  green_standard_field_notes="GREEN: This turn is safe.\fI marked it extra thick\non my map.",
  green_standard_compass_lunch="GREEN: I plan my route.\fIf I'm wrong,\nI'll just try something else.",
  green_standard_competent_detour="GREEN: I took the other path.\fIt was a little longer,\nbut I found more tracks.",

  red_map_city="RED: It's busy here.\fSlow down near corners.\nThen you won't bump into anyone.",
