-- Additional visit lines remain separate from rare-hint selection and contain
-- no invented sightings, encounter promises, or repeatable rewards.
local followups = {
  {"RED", "route", "RED: I'll try a different approach.\fPatience matters here.", "RED: Ich versuche es anders.\fHier braucht man Geduld."},
  {"RED", "city", "RED: My team needed this break.\fSo did I.", "RED: Mein Team brauchte die Pause.\fIch auch."},
  {"BLUE", "route", "BLUE: You can keep watching.\fJust don't get in my way.", "BLUE: Du kannst ruhig zusehen.\fSteh mir nur nicht im Weg."},
  {"BLUE", "city", "BLUE: A break isn't giving up.\fI want my team at its best.", "BLUE: Eine Pause ist kein Aufgeben.\fMein Team soll in Bestform sein."},
  {"GREEN", "route", "GREEN: I'll look further on.\fYou always miss something\nwhen you rush.", "GREEN: Ich sehe mich weiter um.\fWenn man hetzt, übersieht\nman immer etwas."},
  {"GREEN", "city", "GREEN: I'm planning our next stop.\fMy team gets a say, too.", "GREEN: Ich plane unseren\nnächsten Halt.\fMein Team darf mitentscheiden."},
}
for _, line in ipairs(followups) do
  rows[#rows + 1] = {
    id=line[1]:lower() .. "_followup_" .. line[2] .. "_2",
    actor=line[1], role="rival-or-third", mapGroup=line[2],
    progressGate="any", requiredAuthority="none", requiredReceipt="visit-talk",
    weight=1, selectionRule="persisted-repeat-talk-rotation",
    repeatSuppression="alternate-with-route-or-rest-copy", category="followup",
    species="", en=line[3], de=line[4],
    sourceLine="life_of_rival_dialogue_data.lua:followups",
  }
end
for _,row in ipairs(rows)do
  if german[row.id]then row.de=german[row.id]end
  if english[row.id]then row.en=english[row.id]end
end
return rows
